#!/usr/bin/env bash
# probe_D432.sh — проба пункта D432: страж записи открытого пункта читает код 127 как красную «Проверку» (аудит B4).
# Результат: новый открытый пункт, чья «Проверка» не запускается (код 127), НАЗВАН стражем — имя пункта и «(неисполнима: rc=127» — и лёг в журнал видом unrunnable; красная (`false`) проходит МОЛЧА, зелёная (`true`) отбивается.
# Проверка результата: bash hooks/tests/fixtures/probe_D432.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён; 2 — рамка не собралась (stderr называет, что).
# Механизм под судом берётся из CLAUDSOUL_REPO (зелёная сторона подставляет копию с починкой).
# Живой ~/.claude не читается: HOME и STATE_DIR подменены. Судится ВЫВОД стража на payload.
#
# ЧТО СУДИТСЯ И ЧТО НЕТ (17 сентября 2026, D432). Предмет пункта — два состояния под одним значением
# канала (корень R6): «команда сказала „нет“» и «команду не удалось запустить» давали одинаково
# пустой вывод и пустой журнал. Проба судит РАЗЛИЧЕНИЕ — динамическую часть текста стража,
# «<пункт> (неисполнима: rc=127», и вид журнала. Первая редакция искала слово «неисполним» где
# угодно, а оно стоит и в статической части отказа: мутант «126|127 → отказ с другим словом» её
# проходил. УРОВЕНЬ (отказ или контекст) проба не судит намеренно: он меняется по замеру
# (ADR-015; сегодня вид unrunnable — контекст, у него n=0 в журнале исходов), и проба, привязанная к
# уровню, краснела бы от решения, а не от дефекта. Предел: судится одна форма — голая команда с
# кодом 127; маскировку конвейером и цепочкой страж не видит, и это названо в его шапке.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
GUARD="$MECH/hooks/backlog-open-write-guard.sh"
[ -f "$GUARD" ] || { echo "probe_D432: нет $GUARD" >&2; exit 2; }
command -v jq >/dev/null 2>&1 || { echo "probe_D432: нужен jq" >&2; exit 2; }
command -v python3 >/dev/null 2>&1 || { echo "probe_D432: нужен python3" >&2; exit 2; }
T=$(mktemp -d) || { echo "probe_D432: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
mkdir -p "$T/proj" "$T/state" "$T/home"
BL="$T/proj/BACKLOG.md"
printf '# BACKLOG\n\n- ☐ **D10** существующий красный\n  **Проверка.** `false` → 0\n' > "$BL"
MISSING=claudsoul_missing_probe_d432_7429
# Рамка: имя действительно не исполняется — иначе проба судила бы не то состояние.
bash -c "$MISSING" >/dev/null 2>&1; _mrc=$?
[ "$_mrc" -eq 127 ] || { echo "probe_D432: имя $MISSING дало $_mrc, а не 127 — рамка не собралась" >&2; exit 2; }
payload() {  # <id> <команда> → payload Write с новым открытым пунктом
    jq -cn --arg f "$BL" --arg cwd "$T/proj" --arg id "$1" --arg cmd "$2" \
        '{cwd:$cwd, session_id:"probe-d432", tool_name:"Write", tool_input:{file_path:$f, content:("# BACKLOG\n\n- ☐ **D10** существующий красный\n  **Проверка.** `false` → 0\n- ☐ **"+$id+"** новый открытый\n  **Проверка.** `"+$cmd+"` → 0\n")}}'
}
run() { payload "$1" "$2" | HOME="$T/home" STATE_DIR="$T/state" bash "$GUARD" 2>/dev/null; }
denied() { grep -q '"permissionDecision":"deny"' <<< "${1:-}"; }

# Положительные контроли: красная проходит МОЛЧА (это состояние A пары R6 — любой вывод на нём
# значил бы, что страж называет всё подряд), зелёная отбивается — иначе страж нем и судить нечего.
O=$(run D902 false)
[ -z "$O" ] || { echo "probe_D432: контроль — красная «Проверка» (false) не прошла молча: $O" >&2; exit 2; }
O=$(run D903 true)
denied "$O" || { echo "probe_D432: контроль — зелёная «Проверка» (true) не отбита, страж молчит: [$O]" >&2; exit 2; }

# Суд: незапустившаяся команда названа — имя пункта с динамической частью — и записана в журнал.
O=$(run D901 "$MISSING")
# Журнал читается в переменную, утверждение — here-строкой: `… | grep -q` под pipefail врёт под
# нагрузкой (SIGPIPE у левой стороны; страж — test_assert_no_sigpipe).
J=$(cat "$T/state"/backlog-open-write-fired-*.jsonl 2>/dev/null)
if grep -qF 'D901 (неисполнима: rc=127' <<< "$O" \
   && grep -q '"item":"D901".*"kind":"unrunnable"' <<< "$J"; then
    exit 0
fi
echo "probe_D432: дефект — «Проверка» с неисполнимой командой (rc 127) прошла как красная: вывод [${O}], журнал [${J}]" >&2
exit 1
